<?php foreach($coldRows as$row):?>
<section id="cold-room-detail-<?=e($row['key'])?>" class="entity-modal workspace-entity-modal feed-editor production-detail cold-room-detail" role="dialog" aria-modal="true" aria-hidden="true" aria-labelledby="cold-room-detail-title-<?=e($row['key'])?>">
<header><div><p class="page-kicker">BOUCHERIE · CHAMBRE FROIDE</p><h2 id="cold-room-detail-title-<?=e($row['key'])?>"><?=e($row['item_name'])?></h2><p><?=e($row['lot_number'])?></p></div><button type="button" class="modal-close" data-workspace-modal-close aria-label="Fermer les détails du lot">×</button></header>
<div class="feed-form-body"><span class="status-badge ui-status ui-status--<?=e($statusTone($row['state']))?>"><?=e($row['state_label'])?></span>
<dl class="production-detail-summary"><?php foreach(['Au froid'=>$kg($row['physical']).' kg','Réservé'=>$kg($row['reserved']).' kg','Disponible'=>$kg($row['available']).' kg','Type de stock'=>$row['kind_label'],'Date de production'=>date('d/m/Y',strtotime($row['production_date'])),'À consommer jusqu’au'=>date('d/m/Y',strtotime($row['expiry_date']))] as$label=>$value):?><div><dt><?=e($label)?></dt><dd><?=e($value)?></dd></div><?php endforeach;?>
<?php if($row['kind']==='finished'):?><div><dt>Déjà aux comptoirs</dt><dd><?=$kg($row['counter_kg'])?> kg · exclus du poids au froid</dd></div><?php elseif(!empty($row['batch_number'])):?><div><dt>Lot d’élevage d’origine</dt><dd><?=e($row['batch_number'])?></dd></div><?php endif;?></dl>
<p class="livestock-guide">Les quantités réservées sont déjà comprises dans le poids au froid. Elles ne peuvent pas être utilisées pour une autre opération.</p>
<?php if($row['expired']):?><p class="app-alert app-alert-error" role="status">La date limite de consommation est dépassée. Ce lot reste visible dans le stock physique, mais il n’est plus disponible.</p><?php elseif(!in_array($row['status'],['available','reserved'],true)):?><p class="app-alert" role="status">Ce lot est bloqué : <?=e($row['state_label'])?>. Son poids n’est pas compris dans le stock disponible.</p><?php elseif($row['available']<=0):?><p class="app-alert" role="status">Ce lot est entièrement réservé. Aucune quantité n’est disponible pour une autre opération.</p><?php endif;?>
</div><footer><button type="button" class="btn-secondary" data-workspace-modal-close>Fermer</button></footer></section>
<?php endforeach;?>
